export function elevation(lon,lat){const x=((lon+180)*2-.5+720)%720,y=Math.max(0,Math.min(359,(90-lat)*2-.5)),ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy;const at=(a,b)=>heights[Math.min(359,b)*720+(a%720)];return (at(ix,iy)*(1-fx)+at(ix+1,iy)*fx)*(1-fy)+(at(ix,iy+1)*(1-fx)+at(ix+1,iy+1)*fx)*fy;}
